local ActionDarkDreamNewFunctionRankCell = Class("ActionDarkDreamNewFunctionRankCell")

function ActionDarkDreamNewFunctionRankCell:__init()

end

function ActionDarkDreamNewFunctionRankCell:__delete()

end

function ActionDarkDreamNewFunctionRankCell:Awake()
	SetButtonAction(self.BtnCheck,Bind(self,self.OnBtnCheckClick))
end

function ActionDarkDreamNewFunctionRankCell:Refresh(data)
	self.index = data.index
	---@type ActivityCooking.RankData
	self.data = data.input
	
	self.groupId = data.groupId
	
	self:FillSelf()
end

function ActionDarkDreamNewFunctionRankCell:FillSelf()
	local avatarScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
	if avatarScr then
		avatarScr:FreshAvatarFrame(self.data.avatar, self.data.avatarFrame)
		avatarScr:SetCallBack(function()
			if checkNumber(self.data.playerId) > 0 then  -- 机器人不能点
				-- 直接进入个人信息界面2D版
				GameUtils.ShowPlayerInfo(self.data.playerId)
			end
		end)
	end
	
	CfUtils.FillText(self.TxtName, self.data.name)
	CfUtils.FillText(self.TextLevel, "LV." .. tostring(self.data.level))
	CfUtils.FillText(self.TextNumber, self.data.score)
	local status = self.data.ranking > 4 and 4 or self.data.ranking
	CfUtils.SetUISwitchImage(self.ImgRank, status)
	CfUtils.SetUISwitchImage(self.ImgRank2, status)
	
	CfUtils.SetActive(self.ImgRank, self.data.ranking > 0)
	CfUtils.SetActive(self.Txtranking, self.data.ranking > 0)
	CfUtils.SetActive(self.TxtNo, self.data.ranking == 0)
	CfUtils.FillText(self.Txtranking, self.data.ranking)
	local allVos = self:GetRankVos()
	for _, vo in pairs(allVos) do
		if self.data.ranking >= checkNumber(vo.upperLimit) and self.data.ranking <= checkNumber(vo.lowerLimit) then
			CfUtils.RefreshCommonGoodsListLight(
					self.CommonGoodsList, vo.rewards, false, false, true, false, true
			)
			break
		end
	end
end

function ActionDarkDreamNewFunctionRankCell:GetRankVos()
	local data = {}
	local allVos = CfUtils.GetCf(AutoIds.IdSetting6606,"ChaoticRankRewardVo",true)
	for i, v in ipairs(allVos) do
		if v.groupId == checkNumber(self.groupId) then
			table.insert(data,v)
		end
	end
	return data
end

function ActionDarkDreamNewFunctionRankCell:OnBtnCheckClick()
	local data = {}
	for i, v in pairs(self.data.team) do
		table.insert(data,v[1])
	end
	
	GameUtils.ShowCommonTeamsTipsBoard(self.BtnCheck, data, nil, nil, self.data.name)
end

function ActionDarkDreamNewFunctionRankCell:OnDestroy()
	self.controller = nil
	self:Delete()
	self = nil
end

return ActionDarkDreamNewFunctionRankCell